package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
public class MediaLinksTest {
 @Test public void tiktokShortAndFullAndShareCaption(){String user="https://vt.tiktok.com/ZSg42qGJc/";assertEquals(user,MediaLinks.resolve(user));assertEquals(user,MediaLinks.resolve("Veja este vídeo "+user+" no TikTok"));assertEquals("https://www.tiktok.com/@onda/video/7412345678901234567",MediaLinks.resolve("https://www.tiktok.com/@onda/video/7412345678901234567?is_from_webapp=1"));for(String url:new String[]{"https://vm.tiktok.com/ZABCDE123/","https://www.tiktok.com/t/ZABCDE123/","https://m.tiktok.com/share/video/7412345678901234567/"})assertTrue(MediaLinks.isTikTok(MediaLinks.resolve(url)));assertEquals("7412345678901234567",MediaLinks.videoId("https://www.tiktok.com/@onda/video/7412345678901234567?x=1"));}
 @Test public void directSignedUrlsAndLegacyYoutube(){String url="https://cdn.example.com/media/Minha%20aula.MP4?signature=abc%2B123&expires=999";assertEquals(url,MediaLinks.resolve(url));assertEquals("mp4",MediaLinks.extension(url));assertEquals("https://www.youtube.com/watch?v=aqz-KE-bpKQ",MediaLinks.resolve("https://youtu.be/aqz-KE-bpKQ?t=10"));assertTrue(DownloadLinks.isPlaylist(MediaLinks.resolve("https://youtube.com/playlist?list=RDqHZiIxprsrs")));}
 @Test public void rejectOtherSitesCredentialsLocalAndAmbiguous(){for(String url:new String[]{"https://tiktok.com.evil.test/@onda/video/7412345678901234567","https://tiktok.com@evil.com/a.mp4","http://vt.tiktok.com/ZSg42qGJc/","https://www.tiktok.com/@onda","https://www.tiktok.com/@onda/live","https://www.tiktok.com/@onda/photo/7412345678901234567","https://localhost/a.mp4","https://127.0.0.1/a.mp4","https://192.168.1.3/a.mp4","https://cdn.local/a.mp4","https://example.com/a.m3u8","https://example.com:8080/a.mp4","Veja https://vt.tiktok.com/ZSg42qGJc/ e https://example.com/a.mp4"})try{MediaLinks.resolve(url);fail(url);}catch(IllegalArgumentException expected){}}
}
